\text{(a) Let }x_0=\frac{\lambda}{m\omega^2},\quad 
\phi_0(y)=\left(\frac{m\omega}{\pi\hbar}\right)^{1/4}e^{-m\omega y^2/(2\hbar)},\quad
\sigma_x|\pm x\rangle=\pm|\pm x\rangle.\\
