\text{The one-particle ground energy is }
E_0=\frac{\hbar\omega}{2}-\frac{\lambda^2}{2m\omega^2},
\text{ with two degenerate ground states}\\
\psi_{0,+}(x)=\phi_0(x+x_0)|+x\rangle,\qquad
\psi_{0,-}(x)=\phi_0(x-x_0)|-x\rangle,\\
\text{or any normalized linear combination of these two. Since two identical noninteracting fermions fill these two orthogonal ground orbitals,}\\
E_{\text{2 fermions}}=2E_0=\hbar\omega-\frac{\lambda^2}{m\omega^2}.\\[4pt]
\text{(b) For }\Delta H=\epsilon\sigma_x,\text{ the first-order ground-state correction is }
\Delta E_0^{(1)}=-|\epsilon|.\\
\text{A lowest-order ground-state wavefunction giving this correction is }
\psi(x)=
\begin{cases}
\phi_0(x-x_0)|-x\rangle, & \epsilon>0,\\
\phi_0(x+x_0)|+x\rangle, & \epsilon<0,
\end{cases}
\text{ so that }\langle\psi|\epsilon\sigma_x|\psi\rangle=-|\epsilon|.
\end{gathered}

